let rubricSequence=0;
function rubricKey(){return 'RU'+Date.now()+'-'+(++rubricSequence)}
function legacyRubric(){return {id:'LEGACY-DEMO',family:'LEGACY-DEMO',version:1,title:'Provisional four-domain demonstration rubric',state:'PROVISIONAL',criteria:['Concept','Skills','Leadership','Impact'].map(name=>({name,weight:25,max:25,allowNA:false})),rounding:'HALF_UP',decimals:2,naRule:'EXCLUDE_RENORMALIZE',passThreshold:null,certificateThreshold:null}}
function initializeRubrics(){if(!db.rubrics){let r=legacyRubric();db.rubrics=[{...r,id:'RU-DEMO-1',family:'RU-DEMO-1',title:'Four-domain learning assessment — draft example',state:'DRAFT',author:'c1',effective:'2026-01-01',expires:'2027-12-31',purpose:'Demonstration configuration; institutional approval is not implied.'}];save()}}
function rubricById(id){return (db.rubrics||[]).find(r=>r.id===id)}function rubricEditor(){return uid==='c1'}
function rubricVisible(r){return r.state==='APPROVED'||uid==='d1'||uid==='c1'&&r.author===uid}
function rubricValid(r){return !!r.title?.trim()&&r.criteria.length>=2&&r.criteria.length<=8&&r.criteria.every(c=>c.name.trim()&&Number.isFinite(c.weight)&&c.weight>0&&c.weight<=100&&Number.isFinite(c.max)&&c.max>0&&c.max<=1000)&&new Set(r.criteria.map(c=>c.name.toLowerCase().trim())).size===r.criteria.length&&Math.abs(r.criteria.reduce((n,c)=>n+c.weight,0)-100)<1e-8&&['HALF_UP','FLOOR','CEIL'].includes(r.rounding)&&[0,1,2].includes(r.decimals)&&[r.passThreshold,r.certificateThreshold].every(v=>v===null||Number.isFinite(v)&&v>=0&&v<=100)&&validWorkDate(r.effective)&&validWorkDate(r.expires)&&r.effective<=r.expires}
function assessmentSettings(){initializeRubrics();return heading('Assessment rubrics & evaluation settings','Versioned criteria, scales, weights and explicit recognition rules.',rubricEditor()?btn('+ Create rubric','rubricForm()','primary'):'')+`<div class="notice">Demonstration authority: Programme Coordinator authors; Department Head approves. Configured thresholds apply only when explicitly entered and approved. The existing four-domain fallback remains labelled provisional. Nothing is exported as an official MIS/LMS grade.</div>${db.rubrics.filter(rubricVisible).map(r=>`<div class="panel" style="margin-bottom:20px"><div class="top"><div><h2>${esc(r.title)}</h2><div class="meta">${r.id} · v${r.version} · ${esc(r.effective)}–${esc(r.expires)}</div></div>${pill(r.state)}</div><p>${esc(r.purpose)}</p>${rubricDetails(r)}${r.reason?`<div class="notice">${esc(r.reason)}</div>`:''}<div class="buttons">${rubricEditor()&&r.state==='DRAFT'?btn('Edit draft',`rubricForm('${r.id}')`)+btn('Submit for review',`rubricState('${r.id}','UNDER_REVIEW')`,'primary'):''}${uid==='d1'&&r.state==='UNDER_REVIEW'?btn('Approve rubric',`rubricState('${r.id}','APPROVED')`,'primary')+btn('Return with reason',`rubricReturnForm('${r.id}')`):''}${rubricEditor()&&r.state==='APPROVED'&&!db.rubrics.some(v=>v.family===r.family&&v.version>r.version)?btn('Create new version',`rubricRevisionForm('${r.id}')`):''}</div></div>`).join('')||'<div class="panel">No approved rubrics yet. Select Programme Coordinator to prepare a rubric, then Department Head to review it.</div>'}`}
function rubricDetails(r){return tableHTML(['Criterion','Raw scale','Weight','N/A'],r.criteria.map(c=>[esc(c.name),'0–'+c.max,c.weight+'%',c.allowNA?'Allowed; excluded and remaining weights renormalized':'Not permitted']))+`<p class="meta">Rounding: ${r.rounding}, ${r.decimals} decimal places. N/A is distinct from zero. All-N/A evaluations are blocked. Thresholds use the rounded score out of 100.<br>Pass threshold: ${r.passThreshold===null?'Not configured':r.passThreshold+'/100'} · Certificate threshold: ${r.certificateThreshold===null?'Not configured':r.certificateThreshold+'/100'}</p>`}
function rubricForm(id){let r=id?rubricById(id):null;if(!rubricEditor()||r&&r.state!=='DRAFT')return;let base=r||{...legacyRubric(),title:'',effective:localDay(),expires:'2027-12-31',purpose:''};modal(`<h2>${r?'Edit':'Create'} assessment rubric</h2><form onsubmit="saveRubric(event,'${id||''}')">${field('title','Rubric title',base.title)}${field('effective','Effective date',base.effective,'date')}${field('expires','Applicable until',base.expires,'date')}<label>Purpose<textarea name="purpose" required>${esc(base.purpose)}</textarea></label><p>Use 2–8 criteria; leave unused names blank. Weights must total 100%.</p>${Array.from({length:8},(_,i)=>{let c=base.criteria[i];return `<fieldset><legend>Criterion ${i+1}</legend><label>Name<input name="name${i}" value="${esc(c?.name||'')}"></label><label>Weight %<input type="number" step="0.01" min="0" max="100" name="weight${i}" value="${c?.weight??''}"></label><label>Raw maximum<input type="number" step="0.01" min="0.01" max="1000" name="max${i}" value="${c?.max??''}"></label><label>N/A rule<select name="na${i}"><option value="no">Required criterion</option><option value="yes" ${c?.allowNA?'selected':''}>Allow N/A; renormalize remaining weights</option></select></label></fieldset>`}).join('')}<label>Rounding<select name="rounding">${['HALF_UP','FLOOR','CEIL'].map(v=>`<option ${v===base.rounding?'selected':''}>${v}</option>`).join('')}</select></label><label>Decimal places<select name="decimals">${[0,1,2].map(v=>`<option ${v===base.decimals?'selected':''}>${v}</option>`).join('')}</select></label><label>Pass threshold (optional, 0–100)<input name="passThreshold" type="number" min="0" max="100" step="0.01" value="${base.passThreshold??''}"></label><label>Certificate threshold (optional, 0–100)<input name="certificateThreshold" type="number" min="0" max="100" step="0.01" value="${base.certificateThreshold??''}"></label><p>Blank thresholds mean no numeric decision rule. They do not become zero or a default pass mark.</p><button class="primary">Save draft</button> <button type="button" onclick="closeModal()">Cancel</button></form>`)}
function saveRubric(e,id){e.preventDefault();let old=id?rubricById(id):null;if(!rubricEditor()||old&&old.state!=='DRAFT')return;let f=Object.fromEntries(new FormData(e.target)),criteria=[];for(let i=0;i<8;i++){if(!f['name'+i]?.trim())continue;if(!f['weight'+i]?.trim()||!f['max'+i]?.trim())return toast('Every used criterion needs a weight and raw maximum.');criteria.push({name:f['name'+i].trim(),weight:Number(f['weight'+i]),max:Number(f['max'+i]),allowNA:f['na'+i]==='yes'})}let key=old?.id||rubricKey(),r={...(old||{}),id:key,family:old?.family||key,version:old?.version||1,state:'DRAFT',author:uid,title:f.title?.trim(),purpose:f.purpose?.trim(),effective:f.effective,expires:f.expires,criteria,rounding:f.rounding,decimals:Number(f.decimals),naRule:'EXCLUDE_RENORMALIZE',passThreshold:f.passThreshold?.trim()?Number(f.passThreshold):null,certificateThreshold:f.certificateThreshold?.trim()?Number(f.certificateThreshold):null};if(!rubricValid(r)||!r.purpose)return toast('Check criterion names, scales, weights totalling 100%, dates, rounding and thresholds.');if(old)db.rubrics[db.rubrics.indexOf(old)]=r;else db.rubrics.push(r);log(null,'Rubric draft saved '+key);closeModal();render()}
function rubricState(id,next){let r=rubricById(id);if(!r)return;let allowed=uid==='c1'&&r.author===uid&&r.state==='DRAFT'&&next==='UNDER_REVIEW'||uid==='d1'&&r.author!==uid&&r.state==='UNDER_REVIEW'&&next==='APPROVED';if(!allowed)return toast('Independent rubric approval required.');if(!rubricValid(r))return toast('The rubric configuration is invalid.');r.state=next;if(next==='APPROVED'){r.approvedBy=uid;r.approvedAt=new Date().toISOString()}log(null,'Rubric '+id+' → '+next);render()}
function rubricReturnForm(id){modal(`<h2>Return rubric draft</h2><form onsubmit="returnRubric(event,'${id}')"><label>Required corrections<textarea name="reason" required></textarea></label><button class="primary">Return for revision</button> <button type="button" onclick="closeModal()">Cancel</button></form>`)}
function returnRubric(e,id){e.preventDefault();let r=rubricById(id),reason=new FormData(e.target).get('reason').trim();if(uid!=='d1'||r?.state!=='UNDER_REVIEW'||!reason)return;r.state='DRAFT';r.reason=reason;log(null,'Rubric returned '+id+': '+reason);closeModal();render()}
function rubricRevisionForm(id){modal(`<h2>Create rubric version</h2><form onsubmit="reviseRubric(event,'${id}')"><label>Reason<textarea name="reason" required></textarea></label><button class="primary">Create revision draft</button> <button type="button" onclick="closeModal()">Cancel</button></form>`)}
function reviseRubric(e,id){e.preventDefault();let r=rubricById(id),reason=new FormData(e.target).get('reason').trim();if(!rubricEditor()||r?.state!=='APPROVED'||!reason||db.rubrics.some(v=>v.family===r.family&&v.version>r.version))return;let v={...JSON.parse(JSON.stringify(r)),id:rubricKey(),version:r.version+1,state:'DRAFT',reason,previous:r.id,author:uid};delete v.approvedBy;delete v.approvedAt;db.rubrics.push(v);log(null,'Rubric revision created '+v.id+': '+reason);closeModal();render()}
function activityRubric(p){return p.rubricSnapshot||legacyRubric()}
function rubricAssignment(p){let r=activityRubric(p);return `<div class="notice"><strong>Assessment basis:</strong> ${esc(r.title)} · v${r.version} · ${r.state==='PROVISIONAL'?'Provisional demonstration only':'Approved rubric snapshot'}${p.rubricAssignedAt?' · Assigned '+esc(eventTime(p.rubricAssignedAt)):''}</div><details><summary>Criteria and scoring rules</summary>${rubricDetails(r)}</details>${mentor(p)&&['CREATED','PENDING_APPROVAL','APPROVED'].includes(p.state)?`<form onsubmit="assignRubric(event)"><label>Approved current rubric<select name="rubricId">${(db.rubrics||[]).filter(r=>r.state==='APPROVED'&&r.effective<=localDay()&&r.expires>=localDay()).map(r=>`<option value="${r.id}">${esc(r.title)} · v${r.version}</option>`).join('')}</select></label><button>Assign approved version before execution</button></form>`:''}`}
function assignRubric(e){e.preventDefault();let p=current(),id=new FormData(e.target).get('rubricId'),r=rubricById(id);if(!mentor(p)||!['CREATED','PENDING_APPROVAL','APPROVED'].includes(p.state)||Object.values(p.evaluations).some(e=>e.final)||Object.keys(p.certs).length)return toast('Assign before execution and before any finalized evaluation.');if(!r||r.state!=='APPROVED'||r.effective>localDay()||r.expires<localDay())return toast('Select an approved, currently applicable rubric.');p.rubricSnapshot=JSON.parse(JSON.stringify(r));p.rubricAssignedAt=new Date().toISOString();p.rubricAssignedBy=uid;log(p,'Assessment rubric assigned '+r.id+' v'+r.version);render()}
function calculateAssessment(r,values){if(values.length!==r.criteria.length)throw Error('Every criterion must have a score or permitted N/A.');let scores=[],weighted=0,activeWeight=0;for(let i=0;i<r.criteria.length;i++){let c=r.criteria[i],raw=String(values[i]??'').trim();if(raw==='NA'){if(!c.allowNA)throw Error('N/A is not permitted for '+c.name);scores.push(null);continue}if(raw==='')throw Error('Missing score for '+c.name);let score=Number(raw);if(!Number.isFinite(score)||score<0||score>c.max)throw Error('Score outside the raw scale for '+c.name);scores.push(score);weighted+=(score/c.max)*c.weight;activeWeight+=c.weight}if(activeWeight<=0)throw Error('At least one applicable scored criterion is required.');let rawTotal=weighted/activeWeight*100,factor=10**r.decimals,scaled=rawTotal*factor,tolerance=Number.EPSILON*Math.max(1,Math.abs(scaled))*4,total=(r.rounding==='FLOOR'?Math.floor(scaled+tolerance):r.rounding==='CEIL'?Math.ceil(scaled-tolerance):Math.round(scaled+tolerance))/factor;return {scores,rawTotal,total,pass:r.passThreshold===null?null:total>=r.passThreshold,certificateEligible:r.certificateThreshold===null?null:total>=r.certificateThreshold}}
function evaluationSummary(ev){let r=ev.rubricSnapshot,score=ev.total??ev.scores.reduce((n,v)=>n+(v||0),0);return `<p>Evaluation: <strong>${score}/100</strong> · ${ev.final?'Finalized':'Draft'}</p><div class="meta">${r?esc(r.title)+' · v'+r.version:'Legacy provisional four-domain rubric'}${ev.pass===null||ev.pass===undefined?' · Pass rule not configured':ev.pass?' · Pass threshold met':' · Below pass threshold'}${ev.certificateEligible===null||ev.certificateEligible===undefined?'':ev.certificateEligible?' · Certificate threshold met':' · Below certificate threshold'}</div>`}
